package importing

import (
	"context"
	"io"
	"time"
)

// ObjectStore persists private statement files outside database transactions.
// Keys are generated by the service from user/upload UUIDs, never from filenames.
type ObjectStore interface {
	// Put receives the exact known byte length after upload EOF and hashing.
	// It atomically creates only an absent key, never overwriting files or fences.
	// The usecase bounds size and concurrency before calling the adapter.
	Put(ctx context.Context, key string, body io.Reader, size int64) error
	// Open exposes original file bytes only; an erasure fence is logically absent.
	Open(ctx context.Context, key string) (io.ReadCloser, error)
	// Delete confirms a permanent encrypted zero-byte fence at the same key.
	// The fence must block even a late admitted Put; physical deletion is insufficient.
	// It succeeds when the file is already logically absent.
	Delete(ctx context.Context, key string) error
	// List omits fences, retaining Next even when the whole page contains fences.
	List(ctx context.Context, prefix, cursor string) (ObjectPage, error)
}

// Object is cleanup metadata; it contains neither file contents nor its original name.
type Object struct {
	Key        string
	ModifiedAt time.Time
}

// ObjectPage keeps provider pagination opaque to the cleanup usecase.
type ObjectPage struct {
	Objects []Object
	Next    string
}

// ObjectBarrier fences cross-instance object writes against account purge without
// holding a database transaction over network I/O. Implementations use a separate
// bounded connection pool; release must unlock or destroy its session.
type ObjectBarrier interface {
	Shared(context.Context, string) (release func() error, err error)
	Exclusive(context.Context, string) (release func() error, err error)
}
